distancia = ultrasonico.distance_centimeters
if distancia < 15:
    motor_izq.off(); motor_der.off()
    girar(90)
elif distancia < 40:
    motor_izq.on(15); motor_der.on(15)
else:
    motor_izq.on(40); motor_der.on(40)

estado = "buscando"

while True:
    if estado == "buscando":
        # girar en el lugar hasta encontrar la línea
        if color.reflected_light_intensity < 50:
            estado = "siguiendo"

    elif estado == "siguiendo":
        seguir_linea()
        if ultrasonico.distance_centimeters < 15:
            estado = "esquivando"

    elif estado == "esquivando":
        esquivar()
        if ultrasonico.distance_centimeters > 40:
            estado = "buscando"
